=== lineItems.slot.tsx ===
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { InvoiceDetail } from '../../slots/defs/invoiceDetail';
import {
  lineItemsKey,
  listLineItems,
  removeLineItem,
  updateLineItem,
  lineAmount,
  invoiceTotal,
  type LineItem,
} from './lineItemsApi';
import { formatMoney } from '../../ui/money';

// The invoice's line items and what they add up to — one panel filling the invoice.detail region.
// Reads server data under ['invoice-lineitems', invoiceId] (never copied into state); the add form
// shares the key, so a successful add refreshes this with no import between them. Each line can be
// CHANGED (inline) or REMOVED here: both are mutations that invalidate the same key so the list and
// the DERIVED total refetch, plus ['invoices'] so the project's stored amount keeps step. The total
// is derived from the query (never stored), and money renders with two decimals. useState holds only
// what the user is currently typing into the row being edited.
function InvoiceLineItems({ invoiceId }: { invoiceId: number }) {
  const queryClient = useQueryClient();
  const { data: items } = useQuery({
    queryKey: lineItemsKey(invoiceId),
    queryFn: () => listLineItems(invoiceId),
  });

  const [editingId, setEditingId] = useState<number | null>(null);
  const [description, setDescription] = useState('');
  const [qty, setQty] = useState('');
  const [unit, setUnit] = useState('');
  const [unitPrice, setUnitPrice] = useState('');
  const [error, setError] = useState('');

  const refresh = () => {
    void queryClient.invalidateQueries({ queryKey: lineItemsKey(invoiceId) });
    void queryClient.invalidateQueries({ queryKey: ['invoices'] });
  };

  const remove = useMutation({
    mutationFn: removeLineItem,
    onSuccess: refresh,
  });

  const update = useMutation({
    mutationFn: updateLineItem,
    onSuccess: () => {
      setEditingId(null);
      setError('');
      refresh();
    },
  });

  if (!items) {
    return null;
  }

  const startEdit = (item: LineItem) => {
    setEditingId(item.id);
    setDescription(item.description);
    setQty(String(item.qty));
    setUnit(item.unit);
    setUnitPrice(String(item.unitPrice));
    setError('');
  };

  const cancelEdit = () => {
    setEditingId(null);
    setError('');
  };

  const saveEdit = (id: number) => {
    const qtyValue = Number(qty);
    const priceValue = Number(unitPrice);
    if (description.trim() === '') {
      setError('A description is required');
      return;
    }
    if (qty.trim() === '' || Number.isNaN(qtyValue) || qtyValue <= 0) {
      setError('Quantity must be greater than zero');
      return;
    }
    if (unitPrice.trim() === '' || Number.isNaN(priceValue) || priceValue < 0) {
      setError('Price each must be zero or more');
      return;
    }
    update.mutate({
      id,
      description: description.trim(),
      qty: qtyValue,
      unit: unit.trim() === '' ? 'units' : unit.trim(),
      unitPrice: priceValue,
    });
  };

  return (
    <>
      <table data-testid="invoice-lineitems-table">
        <thead>
          <tr>
            <th>Description</th>
            <th>Qty</th>
            <th>Unit</th>
            <th>Unit price</th>
            <th>Amount</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {items.map((item: LineItem) =>
            editingId === item.id ? (
              <tr key={item.id} data-testid={`lineitem-row-${item.id}`}>
                <td>
                  <input
                    data-testid={`lineitem-edit-description-${item.id}`}
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                  />
                </td>
                <td>
                  <input
                    data-testid={`lineitem-edit-qty-${item.id}`}
                    value={qty}
                    onChange={(e) => setQty(e.target.value)}
                  />
                </td>
                <td>
                  <input
                    data-testid={`lineitem-edit-unit-${item.id}`}
                    value={unit}
                    onChange={(e) => setUnit(e.target.value)}
                  />
                </td>
                <td>
                  <input
                    data-testid={`lineitem-edit-unitprice-${item.id}`}
                    value={unitPrice}
                    onChange={(e) => setUnitPrice(e.target.value)}
                  />
                </td>
                <td data-testid="lineitem-amount">
                  {formatMoney(Number(qty) * Number(unitPrice))}
                </td>
                <td>
                  <button
                    data-testid={`lineitem-save-${item.id}`}
                    type="button"
                    onClick={() => saveEdit(item.id)}
                  >
                    Save
                  </button>
                  <button
                    data-testid={`lineitem-cancel-${item.id}`}
                    type="button"
                    onClick={cancelEdit}
                  >
                    Cancel
                  </button>
                </td>
              </tr>
            ) : (
              <tr key={item.id} data-testid={`lineitem-row-${item.id}`}>
                <td data-testid="lineitem-description">{item.description}</td>
                <td data-testid="lineitem-qty">{item.qty}</td>
                <td data-testid="lineitem-unit">{item.unit}</td>
                <td data-testid="lineitem-unitprice">{formatMoney(item.unitPrice)}</td>
                <td data-testid="lineitem-amount">{formatMoney(lineAmount(item))}</td>
                <td>
                  <button
                    data-testid={`lineitem-edit-${item.id}`}
                    type="button"
                    onClick={() => startEdit(item)}
                  >
                    Edit
                  </button>
                  <button
                    data-testid={`lineitem-remove-${item.id}`}
                    type="button"
                    onClick={() => remove.mutate(item.id)}
                  >
                    Remove
                  </button>
                </td>
              </tr>
            ),
          )}
        </tbody>
      </table>
      {error && <p data-testid="lineitem-edit-error">{error}</p>}
      <p data-testid="invoice-amount">{formatMoney(invoiceTotal(items))}</p>
    </>
  );
}

export const contribution = InvoiceDetail.fill({ order: 10, Component: InvoiceLineItems });
=== lineItemsApi.ts ===
import { getJson, postJson } from '../../api/http';

// A line item as the API exposes it — one thing being charged for on an invoice: a description, how
// many, and the price each. The query key is scoped to the invoice, ['invoice-lineitems', invoiceId],
// so each invoice's detail page reads (and invalidates) only its own lines: the list reads the key,
// the add form invalidates it.
export type LineItem = {
  id: number;
  invoiceId: number;
  description: string;
  qty: number;
  unit: string;
  unitPrice: number;
};
export type NewLineItem = {
  invoiceId: number;
  description: string;
  qty: number;
  unit: string;
  unitPrice: number;
};

// The key for one invoice's line items. The list query reads it; a successful add invalidates it so
// the list + the derived total refetch, with no import between the two panels.
export const lineItemsKey = (invoiceId: number) => ['invoice-lineitems', invoiceId] as const;

export const listLineItems = (invoiceId: number): Promise<LineItem[]> =>
  getJson<LineItem[]>(`/api/invoices/lineitems?invoiceId=${invoiceId}`);

export const createLineItem = (body: NewLineItem): Promise<LineItem> =>
  postJson<LineItem>('/api/invoices/lineitems', body);

// Changing a line sends its id alongside the new description, qty and unit price; removing one sends
// just its id. Both are POSTs that invalidate the same ['invoice-lineitems', invoiceId] key the list
// reads, so the list + derived total refetch, plus ['invoices'] so the project's amount keeps step.
export type EditLineItem = {
  id: number;
  description: string;
  qty: number;
  unit: string;
  unitPrice: number;
};

export const updateLineItem = (body: EditLineItem): Promise<LineItem> =>
  postJson<LineItem>('/api/invoices/lineitems/update', body);

export const removeLineItem = (id: number): Promise<LineItem> =>
  postJson<LineItem>('/api/invoices/lineitems/remove', { id });

// A line's own amount, and the whole invoice's amount — both DERIVED from qty and unit price, never
// stored on the client. The project's invoices list shows the same figure (the server keeps the
// invoice's stored amount in step as its lines change).
export const lineAmount = (item: LineItem): number => Number(item.qty) * Number(item.unitPrice);

export const invoiceTotal = (items: LineItem[]): number =>
  items.reduce((sum, item) => sum + lineAmount(item), 0);
=== api.ts ===
import { getJson, postJson } from '../../api/http';

// An invoice as the API exposes it — an amount belonging to a project. The query key is scoped to
// the project, ['invoices', projectId], so each project's detail page reads (and invalidates) only
// its own invoices: the list reads the key, the add form invalidates it.
export type Invoice = {
  id: number;
  projectId: number;
  amount: number;
  status: string;
  issuedDate: string;
  dueDate: string;
};
export type NewInvoice = { projectId: number; amount: number };

// The base key for a project's invoices. The list query appends its current sort below it, so the
// 'id' and 'due' orderings cache separately — while a write still invalidates ['invoices', id] and,
// by prefix, refreshes whichever ordering is on screen.
export const invoicesKey = (projectId: number) => ['invoices', projectId] as const;

// How to order the list: earliest-due-first ('due') or id order (the default). The server reads the
// same `sort` key, so the ordering is applied once, at the source, not re-sorted on the client.
export type InvoiceSort = 'id' | 'due';

export const listInvoices = (projectId: number, sort: InvoiceSort = 'id'): Promise<Invoice[]> =>
  getJson<Invoice[]>(`/api/invoices?projectId=${projectId}&sort=${sort}`);

// One invoice, with its status WORKED OUT from its payments (still owing / part paid / paid). The
// detail page reads this to show the derived status; it is recomputed server-side from the payments.
export const getInvoice = (invoiceId: number): Promise<Invoice> =>
  getJson<Invoice>(`/api/invoices/one?invoiceId=${invoiceId}`);

export const createInvoice = (body: NewInvoice): Promise<Invoice> =>
  postJson<Invoice>('/api/invoices', body);

// Send an invoice — flips DRAFT -> SENT server-side and appends the audit record. Callers invalidate
// ['invoices', projectId] on success so the invoices panel (and the row actions) refetch the status.
export const sendInvoice = (id: number): Promise<Invoice> =>
  postJson<Invoice>('/api/invoices/send', { id });

// Cancel an invoice sent by mistake — flips it to VOID server-side and appends the audit record. A
// VOID invoice stops counting towards what is owed. Callers invalidate ['invoices', projectId] (and
// ['dashboard']) on success so the invoices panel and the home figures refetch.
export const cancelInvoice = (id: number): Promise<Invoice> =>
  postJson<Invoice>('/api/invoices/cancel', { id });

