=== Invoice.java ===
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.time.LocalDate;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * An invoice the user raises against a project: an amount and the id of the project it is for. Maps
 * the {@code invoices} table (Flyway V4__invoices.sql); the id is IDENTITY-generated on create. The
 * amount is a {@link BigDecimal} because it is money (fixed scale, no float drift).
 */
@Entity
@Table(name = "invoices")
public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "project_id", nullable = false)
    private Long projectId;

    @Column(nullable = false)
    private BigDecimal amount;

    /**
     * The lifecycle status of the invoice: DRAFT when raised, SENT once the user sends it, PAID once
     * the user takes payment. Payment is only allowed after it has been sent.
     */
    @Column(nullable = false)
    private String status;

    /** When the invoice went out. */
    @Column(name = "issued_date", nullable = false)
    private LocalDate issuedDate;

    /** When the invoice is due to be paid. */
    @Column(name = "due_date", nullable = false)
    private LocalDate dueDate;

    protected Invoice() {
    }

    public Invoice(Long projectId, BigDecimal amount, LocalDate issuedDate, LocalDate dueDate) {
        this.projectId = projectId;
        this.amount = amount;
        this.status = "DRAFT";
        this.issuedDate = issuedDate;
        this.dueDate = dueDate;
    }

    public Long getId() {
        return id;
    }

    public Long getProjectId() {
        return projectId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    /**
     * Set this invoice's amount to the sum of its line items. The amount is derived from the lines
     * (V15__invoice_line_items.sql), so it is recomputed and stored whenever a line is added.
     */
    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getStatus() {
        return status;
    }

    public LocalDate getIssuedDate() {
        return issuedDate;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    /** Send this invoice — the DRAFT -> SENT transition the send action performs. */
    public void markSent() {
        this.status = "SENT";
    }

    /** Whether this invoice has been sent, and so may be paid. */
    public boolean isSent() {
        return "SENT".equals(this.status);
    }

    /** Mark this invoice paid — the status transition the pay action performs. */
    public void markPaid() {
        this.status = "PAID";
    }

    /**
     * Void this invoice — the terminal transition the cancel action performs when an invoice was
     * sent by mistake. A VOID invoice no longer counts towards what is owed.
     */
    public void markVoid() {
        this.status = "VOID";
    }
}
=== InvoiceView.java ===
package net.officefloor.hq.app;

import java.math.BigDecimal;

/**
 * What the API exposes for an invoice: the shape the front-end renders into the project's invoices
 * table. The amount keeps its scale (a {@link BigDecimal}) so the client formats it to two places.
 */
public record InvoiceView(Long id, Long projectId, BigDecimal amount, String status,
        String issuedDate, String dueDate) {

    public static InvoiceView of(Invoice invoice) {
        return new InvoiceView(invoice.getId(), invoice.getProjectId(), invoice.getAmount(),
                invoice.getStatus(), invoice.getIssuedDate().toString(),
                invoice.getDueDate().toString());
    }

    /**
     * The same view, but with the status WORKED OUT from what has been paid against the invoice (the
     * sum of its payments) rather than a figure flipped by hand. This is how the UI learns whether an
     * invoice is still owing, part paid or settled.
     */
    public static InvoiceView ofDerived(Invoice invoice, java.math.BigDecimal paidSum) {
        return new InvoiceView(invoice.getId(), invoice.getProjectId(), invoice.getAmount(),
                deriveStatus(invoice, paidSum), invoice.getIssuedDate().toString(),
                invoice.getDueDate().toString());
    }

    /**
     * Work out an invoice's status from its payments: PAID once the payments cover its amount,
     * PARTIAL once some has been paid but not all, otherwise the invoice's own lifecycle status
     * (DRAFT before it goes out, SENT once it has). A zero-amount invoice is never PAID off nothing.
     */
    static String deriveStatus(Invoice invoice, java.math.BigDecimal paidSum) {
        // VOID is terminal: a cancelled invoice stays VOID regardless of any payments against it.
        if ("VOID".equals(invoice.getStatus())) {
            return "VOID";
        }
        if (paidSum != null && paidSum.signum() > 0) {
            java.math.BigDecimal amount = invoice.getAmount();
            if (amount != null && amount.signum() > 0 && paidSum.compareTo(amount) >= 0) {
                return "PAID";
            }
            return "PARTIAL";
        }
        return invoice.getStatus();
    }
}
=== GetInvoice.java ===
package net.officefloor.hq.app;

import java.math.BigDecimal;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * GET /api/invoices/one?invoiceId=&lt;id&gt; — one invoice, with its status WORKED OUT from its
 * payments (still owing / part paid / paid) rather than a figure flipped by hand. The invoice detail
 * page reads this to show the derived status; the invoice id arrives as a query parameter. Wired by
 * officefloor/rest/api/invoices/one.GET.yml.
 */
public class GetInvoice {

    public void service(@RequestParam("invoiceId") String invoiceId, InvoiceRepository invoices,
            InvoicePaymentRepository payments, ObjectResponse<InvoiceView> response) {
        Long id = Long.valueOf(invoiceId);
        Invoice invoice = invoices.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("A valid invoice is required"));
        BigDecimal paidSum = payments.findByInvoiceIdOrderByIdAsc(id).stream()
                .map(InvoicePayment::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
        response.send(InvoiceView.ofDerived(invoice, paidSum));
    }
}

