import { useQuery } from '@tanstack/react-query';
import { InvoiceDetail } from '../../slots/defs/invoiceDetail';
import { getInvoiceSummary, invoiceSummaryKey } from './summaryApi';
import { formatMoney } from '../../ui/money';

// An invoice's money summary — one panel filling the invoice.detail region: the SUBTOTAL (what its
// line items add up to), the DISCOUNT taken off it (a percentage of the subtotal), and the final
// TOTAL (subtotal minus the discount). Server data is read under the summary key (never copied into
// state); the server derives the three figures so there is no float drift, and the key shares the
// line items' prefix so a line add/edit/remove refreshes these figures too. This panel owns the
// invoice-amount (the final total) — the line items table above is just the editable lines. Money
// renders with two decimals.
function InvoiceSummary({ invoiceId }: { invoiceId: number }) {
  const { data: summary } = useQuery({
    queryKey: invoiceSummaryKey(invoiceId),
